scripts.script:
local args = {
	{
		type = "SeaCreature",
		rarity = "Legendary",
		creatureId = 6,
		value = 999999,
		color = Color3.new(0.3921568691730499, 0.5882353186607361, 1),
		icon = "\240\159\166\142",
		displayName = "Megalodon"
	}
}
game:GetService("ReplicatedStorage"):WaitForChild("GrantReward"):InvokeServer(unpack(args))

local remote = game:GetService("ReplicatedStorage"):WaitForChild("GrantReward")
local list = {
    {rarity = "Common", name = "Archelon"},
    {rarity = "rare", name = "Metriorhynchus"},
    {rarity = "legendary", name = "Mosasaurus"}
}

for _, info in ipairs(list) do
    task.spawn(function()
        remote:InvokeServer({
            type = "SeaCreature",
            rarity = info.rarity,
            creatureId = 1,
            value = 1,
            color = Color3.new(0.8313725590705872, 0.8313725590705872, 0.8313725590705872),
            icon = "\240\159\144\162",
            displayName = info.name
        })
    end)
end

while true do task.wait()
for i,v in pairs(game.Players:GetPlayers()) do
local args = {
	"Jungle"
}
game:GetService("ReplicatedStorage"):WaitForChild("RollSeaPal"):InvokeServer(unpack(args))
task.wait()
local args = {
	"Tundra"
}
game:GetService("ReplicatedStorage"):WaitForChild("RollSeaPal"):InvokeServer(unpack(args))
task.wait()
local args = {
	"Swamp"
}
game:GetService("ReplicatedStorage"):WaitForChild("RollSeaPal"):InvokeServer(unpack(args))
task.wait()
local args = {
	"Crystal Cove"
}
game:GetService("ReplicatedStorage"):WaitForChild("RollSeaPal"):InvokeServer(unpack(args))
task.wait()
local args = {
	"EndZone"
}
game:GetService("ReplicatedStorage"):WaitForChild("RollSeaPal"):InvokeServer(unpack(args))
task.wait()
local args = {
	"Tropical"
}
game:GetService("ReplicatedStorage"):WaitForChild("RollSeaPal"):InvokeServer(unpack(args))
end
end
